"""ci_text.py — ИСПОЛНЯЕМАЯ часть текста: один дом на все читающие её гейты.

СТРОКИ ЗАПУСКА У ЭТОГО ФАЙЛА НЕТ НАМЕРЕННО: он библиотека, его импортируют, а не
зовут. Shebang означал бы «этот файл запускают», и гейт исполняемости
(internal/repohygiene TestShebangScriptsAreExecutable) справедливо потребовал бы
бита исполнения на то, что исполнять нечем.

ПРЕДМЕТ
-------
Гейт, который ищет слово в СЫРОМ тексте, находит его и там, где оно ничего не
делает: в объяснении, в строке помощи, в закомментированной строке. Оба вида
ошибки уже случались в этом дереве и стоят по-разному:

  · ЛОЖНАЯ НАХОДКА — гейт краснеет на собственной шапке, где перечислены
    узнаваемые формы. Такой гейт снимают при первом же ложном срабатывании;
  · ЛОЖНОЕ МОЛЧАНИЕ — гейт засчитывает ЗАКОММЕНТИРОВАННЫЙ вызов за исполняемый.
    Наблюдалось приёмкой на связи выкладок с чисткой: шаг, где вызов чистки
    закрыт решёткой, был засчитан чистящим — «выкладок семь, находок ноль», а
    артефакт уехал бы сырым.

Второе дороже первого: оно не проявляется никак.

ПОЧЕМУ ОБЩИЙ ФАЙЛ, А НЕ ДВЕ КОПИИ
---------------------------------
Копий этого предиката в дереве уже две (перепись третьей категории и гейт связи
выкладок), и разошлись бы они молча: одна научилась бы видеть хвостовой
комментарий, другая нет, и обе продолжали бы считать — каждая своё. Общий
источник, импортируемый обеими сторонами, — то, чем корпус велит заменять
«вторую копию предиката».

ТРИ ВИДА ТЕКСТА, И У КАЖДОГО СВОЙ ЧИТАТЕЛЬ
------------------------------------------
  · `strip_comment_lines` — убирает СТРОКИ, начинающиеся с `#`. Читатель —
    перепись, считающая упоминания;
  · `shell_executable` — убирает их же, ХВОСТОВОЙ комментарий (отличая его от
    решётки внутри кавычек и от `$#`, `${#x}`, `#!`) и ТЕЛО ВЛОЖЕННОГО
    ДОКУМЕНТА (`<<EOF … EOF`). Читатель — извлечение АРГУМЕНТОВ вызова, где
    кавычки несущие (`--set 'matrix.dir=…'`);
  · `shell_code_only` — всё то же плюс СОДЕРЖИМОЕ КАВЫЧЕК, заменённое пробелами.
    Читатель — признак «вызов ЕСТЬ».

ПОЧЕМУ ПРИЗНАК ВЫЗОВА ЧИТАЕТ ИМЕННО ТРЕТИЙ ВИД, И ЧЕМ ЭТОТ ВЫБОР ОШИБАЕТСЯ
--------------------------------------------------------------------------
Приёмка показала ложное МОЛЧАНИЕ: работа, где единственное упоминание чистки —
строка в кавычках (или строка внутри `<<'EOF'`), проходила гейт связи с кодом 0
и вердиктом «каждая выкладка читается чисткой». Вызова не было бы, а выкладка
объявлялась связанной.

ВЫБРАНО ЧЕСТНОЕ ИСКЛЮЧЕНИЕ, А НЕ РАЗБОР ОБОЛОЧКИ: текст внутри кавычек и внутри
вложенного документа признаком «вызов есть» не считается. Этот выбор ошибается в
БЕЗОПАСНУЮ сторону: настоящий вызов, написанный целиком внутри кавычек
(`bash -c "python3 …"`), будет объявлен ОТСУТСТВУЮЩИМ, то есть даст красное там,
где всё в порядке. Цена — переписать шаг простой строкой; цена обратной ошибки —
сырой артефакт в публичном репозитории, который удалением не отзывается.

ЧЕГО ЗДЕСЬ НЕТ, СКАЗАНО ПРЯМО. Это не разбор оболочки: подстановка команды
(`$(…)`), вложенные кавычки внутри вложенного документа, `eval` и склейка строк
здесь не разбираются. Гейт, которому нужна такая точность, обязан брать разбор, а
не этот файл.
"""

from __future__ import annotations

import re


def strip_comment_lines(text: str) -> str:
    """Текст без строк, начинающихся с `#`. Хвостовые комментарии не трогает."""
    return "\n".join(ln for ln in text.split("\n") if not ln.lstrip().startswith("#"))


# Начало вложенного документа: `<<EOF`, `<<-EOF`, `<< "EOF"`, `<<'EOF'`.
_HEREDOC = re.compile(r"<<-?\s*[\"']?([A-Za-z_][A-Za-z0-9_]*)[\"']?")


def _drop_heredocs(lines: list[str]) -> list[str]:
    """Убирает ТЕЛА вложенных документов, оставляя строки, которые их открывают.

    Тело вложенного документа — ДАННЫЕ. Прежняя редакция этого файла обещала
    обратное («остаётся как есть»), и обещание было ложью: строки, начинающиеся
    с решётки, оттуда удалялись как комментарии. Утверждение приведено к
    поведению, а поведение — к смыслу: данные не код.
    """
    out: list[str] = []
    term: str | None = None
    for line in lines:
        if term is not None:
            if line.strip() == term:
                term = None
            continue
        out.append(line)
        m = _HEREDOC.search(line)
        if m:
            term = m.group(1)
    return out


def shell_executable(text: str) -> str:
    """Исполняемая часть блока оболочки: без комментариев и без тел документов.

    Кавычки СОХРАНЯЮТСЯ: их читает извлечение аргументов, где они несущие
    (`--set 'matrix.dir=…'`). Решётка внутри кавычек комментарием не считается —
    `echo "цена #1"` не обязан терять хвост; формы `$#`, `${#x}`, `#!` — тоже.
    """
    lines = [ln for ln in text.split("\n") if not ln.lstrip().startswith("#")]
    lines = _drop_heredocs(lines)
    return "\n".join(_cut_trailing_comment(ln) for ln in lines)


def shell_code_only(text: str) -> str:
    """То же плюс СОДЕРЖИМОЕ КАВЫЧЕК, заменённое пробелами.

    Признак «вызов есть» читает именно это: строка в кавычках — данные, и вызовом
    она не является. Длина сохраняется заменой на пробелы, чтобы координаты в
    строке не сдвигались.
    """
    return "\n".join(_blank_quoted(ln) for ln in shell_executable(text).split("\n"))


def _blank_quoted(line: str) -> str:
    out: list[str] = []
    quote = ""
    i = 0
    while i < len(line):
        ch = line[i]
        if quote:
            if ch == "\\" and quote == '"' and i + 1 < len(line):
                out.append("  ")
                i += 2
                continue
            if ch == quote:
                quote = ""
                out.append(ch)
            else:
                out.append(" ")
            i += 1
            continue
        if ch in ("'", '"'):
            quote = ch
            out.append(ch)
            i += 1
            continue
        out.append(ch)
        i += 1
    return "".join(out)


def _cut_trailing_comment(line: str) -> str:
    quote = ""
    i = 0
    while i < len(line):
        ch = line[i]
        if quote:
            if ch == "\\" and quote == '"':
                i += 2
                continue
            if ch == quote:
                quote = ""
            i += 1
            continue
        if ch in ("'", '"'):
            quote = ch
            i += 1
            continue
        if ch == "\\":
            i += 2
            continue
        if ch == "#":
            # `$#`, `${#x}`, `#!` — не комментарий. Признак — что стоит СЛЕВА:
            # комментарий начинается на границе слова, а эти формы — нет.
            prev = line[i - 1] if i else ""
            if prev in ("$", "{", "!"):
                i += 1
                continue
            if i and not prev.isspace():
                # `a#b` в оболочке комментарием не является: решётка обязана
                # стоять в начале слова.
                i += 1
                continue
            return line[:i].rstrip()
        i += 1
    return line
